def f(g):
    h=len(g); w=len(g[0])
    out=[r[:] for r in g]
    anchors=[(c,g[0][c]) for c in range(w) if g[0][c]]
    accol=[a[0] for a in anchors]; acolor=[a[1] for a in anchors]
    def mark(r,c,v):
        if out[r][c]==0: out[r][c]=v
    # collect singles per color
    sing={v:[(r,c)] for r in range(h) for c in range(w) for v in [g[r][c]] if g[r][c]!=0 and r!=0}
    for av,acl in zip(acolor,accol):
        vs=sing.get(av,[ ] )
        if vs:
            # vertical from anchor down to lowest single of this color
            rmax=max(r for r,c in vs)
            for rr in range(0,rmax+1): mark(rr,acl,av)
            for r,c in vs:
                step=1 if acl>c else -1
                for cc in range(c,acl+step,step): mark(r,cc,av)
        else:
            # no single: full column
            for rr in range(h): mark(rr,acl,av)
    return out

